import { inspectDefinition } from './contracts.js'
const examples = await fetch('./examples.json').then(r => { if (!r.ok) throw Error('合成样例不可读'); return r.json() })
const key = 'yuanlei-d0-synthetic-v2'
const initial = () => ({projects:Object.fromEntries(['alpha','beta'].map(p=>[p,{home:'delivery',instances:[{id:'delivery',name:'交付观察',template:'delivery-watch',version:1,head:3,active:3,valid:3},{id:'business',name:'经营观察',template:'business-watch',version:1,head:1,active:1,valid:1}],blueprint:'目标：按项目独立核对交付与经营资料。\n约束：个人先用，原始依据和历史必须可查。',editing:false,comments:'',month:'2026-09',sourceState:'ready',result:'r2',opinions:{r1:'',r2:''},resultStatus:'pending',filter:'all',tasks:[],tab:'blueprint',selected:'delivery',compare:'master'}])),inboxRead:false,inboxArchived:false,answer:'answered-not-resumed',guide:true,dark:false,full:false,templateVersion:1,returnContext:null,toast:''})
let state
try { state=JSON.parse(sessionStorage.getItem(key)) || initial() } catch { state=initial() }
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const names={alpha:'甲项目 · 采购',beta:'乙项目 · 交付'}
function route(){const [p='alpha',page='overview']=location.hash.slice(1).split('/'); return {p:['alpha','beta'].includes(p)?p:'alpha',page}}
const link=(p,page,label)=>`<a href="#${p}/${page}">${label}</a>`
const btn=(id,label,primary=false,disabled=false)=>`<button data-action="${id}" ${primary?'class="primary"':''} ${disabled?'disabled':''}>${label}</button>`
const card=(title,body)=>`<section class="card"><h2>${title}</h2>${body}</section>`
const detail=(label,body)=>`<details><summary>${label}</summary>${body}</details>`
const json=value=>`<pre>${esc(JSON.stringify(value,null,2))}</pre>`
function save(){sessionStorage.setItem(key,JSON.stringify(state))}
function notify(text){state.toast=text;save();render()}
function go(page){location.hash=`${route().p}/${page}`}
function templateFor(i){return i.template==='autonomous'?{id:'autonomous',definition:examples.autonomous.definition}:examples.templates.find(t=>t.id===i.template)}
function bindingsFor(i,p){return i.template==='business-watch'?examples.business_bindings[p]:i.template==='autonomous'?{...examples.autonomous.bindings,analysis:{source:'project.dataset',dataset_id:`dataset-${p}-analysis`,revision:1,kind:'analysis'}}:{results:{source:'project.work_results'}}}
function instance(){const d=state.projects[route().p];return d.instances.find(i=>i.id===d.selected&&!i.archived)||d.instances.find(i=>!i.archived)}
function overview(p,d){return `<div class="row"><h1>管理概览</h1><span class="push">${link(p,'manager','管理 Dashboard')} · ${link(p,'business','业务观察')}</span></div><p class="muted">先待验收与异常，再看工作与治理；当前页复用 U5 职责，以下数据是合成。</p><div class="grid">${card('待验收',`<strong>2 份结果 · 1 项工作</strong><p>${link(p,'detail','交付检查 · R2 当前要求')}<br>${link(p,'old','交付检查 · R1 旧依据')}</p>`)}${card('执行异常',`${link(p,'agents','尝试 E2 · 失败，无当前输出')}<p>不把历史失败当作业务受阻。</p>`)}${card('工作与人工事项',`${link(p,'works','项目工作列表')} · ${btn('new-task','新建独立人工工作')}<p>无需先建议题或配 Agent。</p>`)}${card('治理依据',`${link(p,'workbench','蓝图 → 议题 T1 → 有效决定 D1/r2 → 工作 W1')}`)}</div>`}
function workbench(p,d){let content=d.tab==='blueprint'?card('项目蓝图',`${d.editing?`<textarea id="blueprint" aria-label="蓝图草稿">${esc(d.blueprint)}</textarea><div class="toolbar">${btn('save-blueprint','保存合成草稿',true)}${btn('cancel-blueprint','返回阅读')}</div>`:`<p style="white-space:pre-wrap">${esc(d.blueprint)}</p>${btn('edit-blueprint','编辑蓝图')}`}${detail('蓝图历史与维护', '<p>历史 v1：保留原方向。新建、重命名、归档、删除沿用产品；此稿未模拟真实文件写入。</p>')}`):d.tab==='topics'?`<div class="split"><section class="card"><h2>议题列表</h2><input aria-label="筛选议题" placeholder="编号或标题"><p><strong>T1 · 交付标准</strong><br><span class="badge">已准入 · 执行中</span></p><p>T2 · 需求补充<br><span class="badge">待审核</span></p></section>${card('T1 · 交付标准',`<h3>问题与目标</h3><p>两份交付依据不同，必须定位准确结果。</p><h3>当前有效决定 D1/r2</h3><p>核对修订二与真实文件后办理，R1/r1仅作历史对照。</p><div class="toolbar">${link(p,'detail','关联正式工作 W1 · 交付检查')}${btn('admit','创建或关联正式工作',true)}</div>${detail('讨论与回复',`<p>讨论 C1：旧要求如何对照？回复 C2：保留快照。</p><textarea id="discussion" aria-label="讨论草稿">${esc(d.comments)}</textarea>`)}${detail('决定历版与修改/重开时间线','<p>D1/r1：旧要求；D1/r2：补充文件与对照。后端状态约束继续有效。</p>')}${detail('全部维护动作','<p>编辑、继续讨论、归档、重开、拒绝、批准、勘误沿用既有治理操作；此稿只展示位置，不执行业务决定。</p>')}`)}</div>`:card('工作建议 S1',`<p>由 T1/D1/r2 形成，建议：核对交付；不能把建议审核当执行。</p>${btn('admit','创建或关联正式工作',true)}${detail('已有关联和重复准入','<p>合成映射固定 W1；再次关联只打开同一工作。</p>')}`);return `<h1>项目治理工作台</h1><div class="toolbar">${btn('tab-blueprint','蓝图')}${btn('tab-topics','议题与决策')}${btn('tab-suggestions','工作建议')}${btn('compare-workbench','同场景：分栏 / 长页对照')}</div>${d.compare==='long'?'<div class="callout">长页对照：相同 T1、D1/r1、D1/r2、W1 全文连续阅读，编辑与讨论同页，当前决定易落到下方。推荐分栏+阅读模式；窄屏单页。</div>':''}${content}<p class="muted">旧 query/hash 将定位同一对象；源码治理语义不在原型中改写。</p>`}
function works(p,d){return `<h1>项目工作列表</h1><div class="toolbar">${btn('filter-all','全部')}${btn('filter-review','待验收')}${btn('filter-blocked','受阻')}${btn('new-task','新建独立人工工作',true)}</div><p>筛选：${esc(d.filter)} · ${names[p]}，同名工作仍有准确项目身份。</p><div class="table-wrap"><table><thead><tr><th>工作</th><th>业务状态 / 需人动作</th><th>最新尝试 / 来源</th></tr></thead><tbody>${d.filter==='blocked'?`<tr><td>${link(p,'agents','W2 · 整理资料')}</td><td>受阻 · 缺少资料</td><td>E2失败 / 处理者状态未接入</td></tr>`:`<tr><td>${link(p,'detail','W1 · 交付检查')}</td><td>进行中 · R2待验收</td><td>人工提交 / T1 D1/r2</td></tr>${d.tasks.map(t=>`<tr><td>${esc(t)}</td><td>待办 · 人工独立</td><td>无议题/Agent前置</td></tr>`).join('')}`}</tbody></table></div>${detail('保留看板 / 甘特 / 日期与状态操作','<p>三种视图和全部既有操作保留；此稿只模拟任务行与筛选，不保存真实任务。</p>')}`}
function resultPage(p,d,old=false){if(old)d.result='r1';let id=d.result, isOld=id==='r1';return `<h1>${names[p]} / W1 · 交付检查</h1><div class="toolbar">${btn('return','返回来源')}${btn('result-r1','R1 · 旧要求 1')}${btn('result-r2','R2 · 当前要求 2')}</div>${card(`交付 ${id.toUpperCase()} · ${isOld?'待验收 / 旧依据':d.resultStatus}`,`<h3>结果摘要</h3><p>${isOld?'按修订一提交清单，未补对照。':'按修订二补充文件与对照结论。'}</p>${isOld?'<div class="callout">旧依据可核对并记未接受，接受需要补充当前要求交付。</div>':''}<h3>提交时验收条件 · 修订 ${isOld?1:2}</h3><p>${isOld?'核对合成清单。':'核对合成清单、文件并补充对照结论。'}</p>${detail('当前条件 / 修订 2','<p>核对合成清单、文件并补充对照结论。</p>')}<h3>交付文件与依据</h3>${link(p,'file','查看合成交付.md')}<p class="muted">纯合成文本，没有真实文件鉴权；产品沿用 Workspace。</p><textarea id="opinion" aria-label="验收意见">${esc(d.opinions[id])}</textarea><div class="toolbar">${btn('not-accepted','未接受')}${btn('accept-result','接受当前结果',true,isOld)}${btn('result-conflict','模拟409保留意见')}</div>`)}${detail('来源、执行历史与工作管理','<p>T1 → D1/r2 → W1。Git、Issue、委派、附件、参考、反馈和负责人设置沿用原产品；此稿未执行。</p>')}${detail('协作补充与未解决项','<p>来源 operation/attempt 精确标明；未解决阻塞需首层提示。实际投影待C0/C5。</p>')}`}
function inbox(p,d){return `<h1>跨项目收件箱</h1><div class="toolbar">${btn('read','切换已读')}${btn('archive','切换通知归档')}${btn('open-beta','打开乙项目同名交付')}</div><div class="grid">${card('需本人关注 · Q2',`<strong>乙项目 / W1 · 交付检查</strong><p>通知：${state.inboxRead?'已读':'未读'} / ${state.inboxArchived?'已归档':'未归档'}</p><p>真实问题设计投影：已答复，尚未采用/恢复。</p>${link('beta','problem','查看送达与恢复')}<p class="muted">已读/归档都不关闭问题，以下时间线为设计模拟。</p>`)}${card('交付入口',`${link('alpha','detail','甲项目 / W1 · 交付检查 · R2')}<br>${link('beta','detail','乙项目 / W1 · 交付检查 · R2')}`)}</div>${detail('普通通知','<p>模型/执行结束等通知只提供来源，不全部转成人待办。</p>')}`}
function problem(p,d){return `<h1>${names[p]} / W1 / Q2</h1><div class="callout">设计投影 · C0/C5未接入。已答 ≠ 已采用 ≠ 已恢复。</div>${card('当前处理',`<p>当前责任节点 C，答复 r2 已送达。${state.answer==='resumed'?'合成状态：准确尝试已采用并恢复。':'尚未采用，执行未恢复。'}</p>${btn('resume','模拟准确尝试采用/恢复')} ${link(p,'inbox','返回收件箱')}`)}${card('逐级回溯',`<ol><li>C 缺资料 → B 不能解答</li><li>B → A，A 超出权限 → H</li><li>H 答 r2 → A 核对 → B 转答 → C</li><li>答复引用 Q2/attempt-2；旧 Q1/attempt-1 不恢复</li></ol>${detail('原问题、各级分析与授权','<p>问题：缺少交付标准。答复：按修订二核对。正式Decision授权须由C4记录；原型无批准能力。</p>')}`)}`}
function agents(p,d){return `<h1>项目智能体 / 研究助手</h1><p>第一负责人、当前执行者和求助处理者分别显示；运行成功不代表工作验收。</p><div class="grid">${card('接收待接受',`<p>E3 / W3 · 新工作</p>${btn('accept-execution','模拟接受进入队列')}`)}${card('执行与异常',`<p>E2 / W2 · 失败；没有新结果</p>${link(p,'execution','定位 W2 / E2 同次执行历史')}`)}${card('交付',`${link(p,'detail','准确 R2 交付入口')}<p>不能从相邻Run猜结果。</p>`)}${card('求助',`${link(p,'problem','Q2 已答未恢复')}<p>逐级状态为设计模拟，真实处理者待C5。</p>`)}</div>${detail('接收配置与模型','<p>自动接受默认关闭，模型沿用已有工作台配置。</p>')}${detail('日志、轨迹与历史','<p>按attempt/Run准确读取；配置和轨迹不占首层。</p>')}`}
function library(p,d){return `<h1>Dashboard 模板与素材库</h1><p>平台资源 · 内置 / 个人共享 / 项目专属；只复用结构，不携带项目数据。</p><div class="grid">${examples.templates.map(t=>card(`${t.name} @${state.templateVersion}`,`<p>${t.id==='delivery-watch'?'指标+准确结果列表 / grid':'月趋势+区域表+分析说明 / grid'}</p><div class="toolbar">${btn(`derive-${t.id}`,'派生到当前项目',true)}</div>${detail('输入 / 结构 / 导航契约',json(t.definition))}`)).join('')}</div><div class="toolbar">${btn('template-upgrade','模拟库发布 v2（实例仍锁 v1）')}${btn('create-autonomous','自主 stack 结构')}${link(p,'compare','同样例比较受控定义 / R2 / 静态')}</div>${card('素材注册说明',`<p>${examples.materials.join(' · ')}</p><p>可信组件版本发布；图片与执行组件分开。这里没有任意代码上传执行。</p>${link(p,'rules','查看生成规则与非法样例')}`)}`}
function manager(p,d){const i=instance();return `<h1>${names[p]} / 管理 Dashboard</h1><p>当前业务首页：${esc(d.home)}；管理概览始终可达。每个实例独立稳定修订。</p><div class="table-wrap"><table><tr><th>实例 / 草稿模板锁定</th><th>草稿head / 生效</th><th>操作</th></tr>${d.instances.filter(x=>!x.archived).map(x=>`<tr><td>${esc(x.name)} · ${esc(x.id)}<br>${x.template==='autonomous'?'自主定义 / 无模板':esc(x.template)+'@'+x.version}</td><td>${x.head} / ${x.active||'未启用'}</td><td>${btn(`select-${x.id}`,'选择实例')}${btn(`home-${x.id}`,'设为业务首页',false,!x.active)}</td></tr>`).join('')}</table></div>${card(`当前选择：${esc(i.name)}`,`<p>${i.template==='autonomous'?'自主定义 / 无模板':'模板 '+esc(i.template)+'@'+i.version} · 绑定限定 ${names[p]}（无凭据）</p><p>草稿 ${i.head} / 稳定 ${i.active||'无'} / 验证 ${i.valid===i.head?'当前修订通过':'待验证'}</p><div class="toolbar">${btn('save-draft','保存新合成草稿')}${btn('validate','验证当前草稿')}${btn('bad-definition','注入非法定义')}${btn('good-definition','恢复合法定义')}${btn('concurrent','模拟竞争更新')}${i.conflict?btn('read-latest','读取最新并保留草稿'):''}</div><div class="toolbar">${btn('preview','预览指定草稿')}${btn('activate','启用准确草稿',true,i.valid!==i.head)}${btn('rollback','回退稳定历史',false,!i.previous)}${btn('upgrade-instance','模板升级为新草稿',false,i.template==='autonomous')}${btn('extract','提取个人模板结构')}${btn('archive-instance','归档当前实例')}</div>${i.errors?.length?`<div class="callout">${json(i.errors)}</div>`:''}${detail('定义与项目绑定',json({definition:i.bad?examples.illegal.definition:templateFor(i).definition,bindings:i.bad?examples.illegal.bindings:bindingsFor(i,p)}))}`)}${card('启用政策',`<p>当前：${i.policy||'manual'}（只模拟策略，无真实授权）</p>${btn('policy','在 manual / fixed-template 间对照')}<p>自动范围仅精确模板/素材/字段；不包含业务数据采纳或正式批准。</p>`)}${detail('旧静态页 / 归档历史',`<p>旧 HTML 仍由静态service及空sandbox读取，原型不扩大执行权限。归档保留修订，不能删除正在引用的模板版本。</p><p>已归档：${d.instances.filter(x=>x.archived).map(x=>esc(x.name)+'@r'+x.active).join('、')||'无'}</p>`)}`}
function business(p,d,preview=false){const i=preview?instance():(d.instances.find(x=>x.id===d.home)||d.instances[0]);let value=p==='alpha'?18000:4200;return `<div class="row"><h1>${names[p]} / 业务观察</h1>${btn('fullscreen',state.full?'退出全屏':'请求全屏')} ${link(p,'overview','回管理概览')} ${link(p,'manager','管理 Dashboard')}</div><p>实例 ${esc(i.id)} · ${preview?"草稿预览 r"+i.head:"当前稳定 r"+i.active} · ${i.template==='autonomous'?'自主定义 / 无模板':'模板锁定 '+i.template+'@'+(preview?i.version:(i.stableTemplateVersion||1))} · 定义布局 ${i.template==='autonomous'?'stack':'grid'} · 全部数据为合成</p><div class="toolbar"><label>月份 <select id="month"><option ${d.month==='2026-08'?'selected':''}>2026-08</option><option ${d.month==='2026-09'?'selected':''}>2026-09</option></select></label>${btn('refresh-data','刷新合成数据')}<label>数据状态 <select id="source-state">${['ready','missing','stale','error'].map(s=>`<option ${d.sourceState===s?'selected':''}>${s}</option>`).join('')}</select></label></div><p class="muted">来源：${i.template==='business-watch'?(p==='alpha'?'dataset-alpha-sales@3':'dataset-beta-sales@7')+'；CNY':'work.results.v1 / work.summary.v1 / analysis.note.v1'}；as_of=2026-10-09T08:00Z。没有请求产品数据。</p>${d.sourceState==='ready'?'':`<div class="callout">${d.sourceState}: ${d.sourceState==='missing'?'缺数，不显示伪造0':'保留上次合成值并显示过期/失败，管理仍可达'}</div>`}${i.template==='autonomous'?'<div class="card"><h2>自主 stack · 执行路径</h2><p>分析（合成）→ 状态分组 → 准确交付</p><div class="lanes"><section class="card">待接受 E3</section><section class="card">执行异常 E2</section><section class="card">交付 R2</section></div></div>':i.template==='delivery-watch'?'<div class="card"><h2>交付观察 · 指标 + 列表</h2><strong>2 份合成结果</strong><p>R1旧要求 / R2当前要求，点击下面的准确交付进入办理。</p></div>':''}<div class="grid">${i.template==='business-watch'?card('业务月度 / CNY',d.sourceState==='missing'?'<p>尚无数据，请绑定已采纳数据集。</p>':`<div class="bars"><div class="bar" style="height:90px">8月<br>${value*.7}</div><div class="bar" style="height:155px">9月<br>${value}</div></div>`):''}${card('交付与分析',`<p>分析：合成报告，不作为独立核验。</p>${btn('drill','准确 W1/R2 → 办理 → 回观察',true)}<p>旧结果、当前交付和数据时间分别保留。</p>${i.template==='business-watch'?detail('区域明细 / 来源完整性','<p>华东 2条合成数据；缺失1条，显示完整性限制。</p>'):detail('结果 / 来源完整性','<p>正式结果与分析说明分槽读取；分析仅合成样例。</p>')}`)}</div>`}
function rules(){return `<h1>生成能力说明 / rule@1</h1><p>当前支持规则、素材、输入及预算需要由产品工具发现；此稿静态提供合成说明。</p>${card('正确工作流','<ol><li>读取规则和当前版本/授权</li><li>选择模板或自主定义并绑定本人项目数据</li><li>CAS保存草稿，验证指定修订</li><li>预览示例/实际数据有明确标记</li><li>manual本人启用，fixed-template按明确授权启用</li><li>回读准确版本、来源时间；失败保留稳定版</li></ol>')}${detail('非法定义与有位置的错误',json({illegal:examples.illegal,expected_errors:examples.expected_errors}))}${detail('完整机器可读样例',json(examples))}`}
function compare(){return `<h1>同任务：表达与代价</h1><div class="table-wrap"><table><tr><th>要求</th><th>受控定义（推荐）</th><th>隔离 Vue R2</th><th>静态兼容</th></tr><tr><td>交付指标/表格/准确返回</td><td>可组合，数据/导航确定校验</td><td>自由度高，仍须授权服务/隔离协议</td><td>只能快照，不具备动态钻取</td></tr><tr><td>趋势/区域表/分析</td><td>多槽+单位，布局可派生</td><td>新图形表达更自由，多构建依赖维护</td><td>静态表现好，更新需重生成</td></tr><tr><td>自由弧线布局/标签避让</td><td>当前素材不足；专用可信组件有成本</td><td>保留需求触发，不能信任任意代码</td><td>可静态图，不满足交互</td></tr></table></div><p>本页是成本对照，没有扩大 R2 或提供运行生成代码的按钮。</p>`}
function render(){const {p,page}=route(),d=state.projects[p];document.body.classList.toggle('dark',state.dark);document.body.classList.toggle('full',state.full);const views={overview,workbench,works,inbox,agents,library,manager,business,preview:(p,d)=>business(p,d,true),execution:(p,d)=>`<h1>${names[p]} / W2 · 整理资料 / E2</h1><div class="callout">合成同次执行：E2失败，无结果。W1/R2属于另一工作，不能替代此尝试交付。</div><p>第一负责人：本人；执行者：研究助手；求助处理者：状态未接入。</p>${detail('执行轨迹与错误','<p>缺少资料导致失败；旧尝试E1仅作历史。</p>')}${link(p,'agents','返回选中项目 Agent 队列')}`,detail:(p,d)=>resultPage(p,d),old:(p,d)=>resultPage(p,d,true),problem,rules,compare,file:()=>`<h1>合成交付.md</h1><p>本稿只呈现合成文件正文：清单与对照结论已列出，无真实产物或历史字节验证。</p>${btn('file-return','回准确结果')}`};document.querySelector('#app').innerHTML=`<header><strong>元垒 · D0 全景连续稿</strong><span class="badge">设计推荐 / 合成数据 / 未连接产品</span><label>项目 <select id="project">${Object.entries(names).map(([id,name])=>`<option value="${id}" ${p===id?'selected':''}>${name}</option>`).join('')}</select></label>${btn('theme','切换主题')}${btn('guide','任务指引')}${btn('reset','重置合成状态')}</header>${state.guide?`<section class="task-guide"><strong>连续任务，不自动记录用户完成</strong><ol><li>管理→工作台→议题决定→正式工作→R1旧依据/R2当前交付→意见/文件→来源</li><li>收件箱→乙项目同名工作→Q2已答未恢复→时间线→返回</li><li>库→派生/自主→验证→预览→启用→业务筛选→准确结果→回观察→回退</li></ol></section>`:''}${state.toast?`<div class="toast" role="status">${esc(state.toast)} ${btn('dismiss','关闭提示')}</div>`:''}<div class="layout"><nav aria-label="平台与项目导航">${[['overview','项目 · 管理概览'],['workbench','治理工作台'],['works','项目工作'],['inbox','平台 · 跨项目收件箱'],['agents','项目 Agent'],['business','业务观察'],['manager','项目 Dashboard 管理'],['library','平台 · 模板/素材'],['rules','生成规则'],['compare','同任务对照']].map(([id,title])=>`<a class="${page===id?'active':''}" href="#${p}/${id}">${title}</a>`).join('')}</nav><main>${(views[page]||overview)(p,d)}<div class="foot">未实现：真实API/权限/数据库/Agent/发布/数据验证/协作恢复/动态Vue运行时。这里的“保存/启用/恢复”仅模拟，可撤销，不作为产品证据。</div></main></div>`;save()}
document.addEventListener('input',e=>{const d=state.projects[route().p];if(e.target.id==='opinion')d.opinions[d.result]=e.target.value;if(e.target.id==='blueprint')d.blueprint=e.target.value;if(e.target.id==='discussion')d.comments=e.target.value;save()})
document.addEventListener('change',e=>{const {p}=route(),d=state.projects[p];if(e.target.id==='project'){location.hash=`${e.target.value}/${route().page}`;return}if(e.target.id==='month')d.month=e.target.value;if(e.target.id==='source-state')d.sourceState=e.target.value;save();render()})
document.addEventListener('click',e=>{const target=e.target.closest('a[href]');if(target?.getAttribute('href')?.match(/\/(detail|old)$/)){state.origin={p:route().p,page:route().page};state.returnContext=null;if(target.getAttribute('href').endsWith('/detail'))state.projects[target.getAttribute('href').slice(1).split('/')[0]].result='r2';save()}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;const {p,page}=route(),d=state.projects[p],i=instance();state.toast='';if(action.startsWith('tab-')){d.tab=action.slice(4);render();return}if(action.startsWith('filter-')){d.filter=action.slice(7);render();return}if(action.startsWith('result-')&&['r1','r2'].includes(action.slice(7))){d.result=action.slice(7);go('detail');render();return}if(action.startsWith('derive-')){const t=action.slice(7),id=`instance-${d.instances.length+1}`;d.instances.push({id,name:examples.templates.find(x=>x.id===t).name,template:t,version:state.templateVersion,head:1,active:0,valid:0});d.selected=id;go('manager');return}if(action.startsWith('select-')){d.selected=action.slice(7);render();return}if(action.startsWith('home-')){d.home=action.slice(5);notify('仅合成：首页指针切换，另一个实例稳定修订仍保留。');return}
switch(action){case 'theme':state.dark=!state.dark;render();break;case 'guide':state.guide=!state.guide;render();break;case 'reset':state=initial();go('overview');render();break;case 'dismiss':state.toast='';render();break;case 'edit-blueprint':d.editing=true;render();break;case 'cancel-blueprint':case 'save-blueprint':d.editing=false;notify('合成草稿保留；没有调用蓝图服务。');break;case 'compare-workbench':d.compare=d.compare==='master'?'long':'master';render();break;case 'admit':notify('合成关联 W1；产品重复准入由现有事务保证。');go('works');break;case 'new-task':d.tasks.push(`人工独立事项 ${d.tasks.length+1}`);notify('合成人工工作行已创建，无议题/Agent。');go('works');break;case 'read':state.inboxRead=!state.inboxRead;render();break;case 'archive':state.inboxArchived=!state.inboxArchived;render();break;case 'open-beta':state.origin={p,page:'inbox'};state.returnContext=null;state.projects.beta.result='r2';location.hash='beta/detail';break;case 'resume':state.answer='resumed';notify('仅模拟 Q2/attempt-2 采用与恢复，产品能力仍未接入。');break;case 'accept-execution':notify('仅模拟待接受→队列；未启动Run。');break;case 'accept-result':if(d.result==='r2'){d.resultStatus='accepted';d.opinions.r2='';notify('仅模拟接受 R2；工作完成是另一动作，未写业务状态。')}break;case 'not-accepted':notify('仅模拟意见处理，原型未修改真实交付。');break;case 'result-conflict':notify('模拟409：意见保留，核对最新结果后再办；未重放。');break;case 'return':if(state.returnContext&&state.returnContext.p===p){d.month=state.returnContext.month;state.full=state.returnContext.full;state.toast=`恢复观察 ${state.returnContext.instance}@r${state.returnContext.revision} / ${d.month}；仅合成`;go('business')}else if(state.origin?.page==='inbox'){location.hash=`${state.origin.p}/inbox`}else go(state.origin?.p===p?state.origin.page:'works');break;case 'file-return':go('detail');break;case 'template-upgrade':state.templateVersion=2;notify('合成模板 v2 发布；现有实例仍精确锁定原版本。');break;case 'create-autonomous':{const id=`flow-${d.instances.length+1}`;d.instances.push({id,name:'自主执行观察',template:'autonomous',version:1,head:1,active:0,valid:0});d.selected=id;go('manager');break}case 'save-draft':if(i.conflict){notify('CAS409：合成输入保留，请读取最新后合并；稳定版本未变。');break}i.head++;i.valid=0;notify('新草稿修订已保存，稳定版未变。');break;case 'read-latest':i.conflict=false;notify('已读取合成最新head，输入保留；请合并后显式保存。');break;case 'validate':i.errors=inspectDefinition(i.bad?examples.illegal.definition:templateFor(i).definition,i.bad?examples.illegal.bindings:bindingsFor(i,p),examples.materials);i.valid=i.errors.length?0:i.head;notify(i.errors.length?'结构检查失败：错误位置可读，稳定页未变。':'合成有限结构检查通过；未验证生产权限/真实源/发布策略。');break;case 'bad-definition':i.bad=true;i.valid=0;render();break;case 'good-definition':i.bad=false;i.valid=0;render();break;case 'concurrent':i.head++;i.valid=0;i.conflict=true;notify('合成竞争方更新head；下一保存将409，输入不自动重放。');break;case 'preview':state.toast=`草稿r${i.head}预览 / 示例数据，不是稳定启用`;go('preview');break;case 'activate':if(i.valid===i.head){i.snapshots??={};if(i.active)i.snapshots[i.active]={version:i.stableTemplateVersion||1};i.snapshots[i.head]={version:i.version};i.previous=i.active||null;i.active=i.head;i.stableTemplateVersion=i.version;notify('仅合成启用准确修订；要成为业务首页需显式选择。')}break;case 'rollback':if(i.previous){const prior=i.active;i.active=i.previous;i.stableTemplateVersion=i.snapshots?.[i.active]?.version||1;i.previous=prior;notify('合成回退稳定定义/绑定；不会撤销数据或业务操作。')}break;case 'upgrade-instance':i.version=state.templateVersion;i.head++;i.valid=0;notify('锁定模板升级为新草稿，稳定修订未变；产品需保存逐修订完整锁定版本。');break;case 'extract':notify('提取结构/逻辑输入槽；去除项目绑定、行数据、凭据和Run身份。');break;case 'archive-instance':if(d.home===i.id){notify('拒绝：当前首页须先选替代或回管理，不能悄悄归档。')}else{i.archived=true;d.selected=d.instances.find(x=>!x.archived).id;notify('合成软归档：活动列表移出，历史保留。')}break;case 'policy':i.policy=i.policy==='fixed-template'?'manual':'fixed-template';notify('仅对照策略；原型不产生真实授权，也不默认采纳生成数据。');break;case 'refresh-data':notify('合成刷新：来源版本和as_of可见；未请求真实API。');break;case 'fullscreen':state.full=!state.full;render();break;case 'drill':if(page==='preview'){notify('草稿预览未生成稳定返回会话；请启用后从业务观察核对返回。');break}state.returnContext={p,instance:d.home,revision:d.instances.find(x=>x.id===d.home).active,month:d.month,full:state.full};state.full=false;d.result='r2';go('detail');break}
save()})
window.addEventListener('hashchange',render)
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.full){state.full=false;render()}})
render()
